-- =====================================================================
-- Dados de DEMONSTRAÇÃO do SGC (apresentação do TCC).
-- NÃO é migração do Flyway: só é aplicado pelo DemoDataSeeder com o perfil
-- "demo" ativo, uma única vez (marcador: empresa com CNPJ 11.222.333/0001-81).
-- Gerado por script determinístico; datas são relativas ao momento da carga
-- (NOW() - INTERVAL ...), então os últimos ~6 meses sempre têm movimento.
-- Senha de todos os usuários de demonstração: Demo@123
-- Parte das OS concluídas já vem avaliada (nota de 1 a 5), como se o solicitante
-- tivesse respondido "Nota #<id> <nota>" pelo WhatsApp.
-- Os números aqui são FICTÍCIOS: servem para demonstrar o sistema, não como
-- resultado de pesquisa.
-- =====================================================================

-- Empresa e prédios
VALUES ('Faculdade Princesa do Oeste (Demonstração)', '11.222.333/0001-81', 'contato@demo.sgc.local', '(88) 3000-0000', TRUE);
SET @company = LAST_INSERT_ID();

VALUES ('Bloco Acadêmico A', 'DEMO-A', 'Rua da Demonstração, 100 - Crateús/CE', @company, TRUE, NOW() - INTERVAL 400 DAY);
SET @bloco_a = LAST_INSERT_ID();
VALUES ('Bloco Administrativo', 'DEMO-B', 'Rua da Demonstração, 200 - Crateús/CE', @company, TRUE, NOW() - INTERVAL 400 DAY);
